import{z as o,x as C,o as B,c as s,q as n,j as r,D as e,d as a,s as l,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"漂移管理","description":"","frontmatter":{"title":"漂移管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-drift-management.md","filePath":"quant/fml-drift-management.md","lastUpdated":1791063341000}'),d={name:"quant/fml-drift-management.md"};function m(p,E,D,f,u,h){const t=C("Mermaid");return B(),s("div",null,[E[2]||(E[2]=n('<h1 id="漂移管理" tabindex="-1">漂移管理 <a class="header-anchor" href="#漂移管理" aria-label="Permalink to &quot;漂移管理&quot;">​</a></h1><div class="epigraph"><p>漂移管理的前提是把漂移拆开：特征的分布变了、关系变了、还是管道变了——三者的响应完全不同，合并成一句「模型旧了」只会带来错误的补丁。</p><footer>—— 据 Gama et al., ACM Computing Surveys, 2014；McLean and Pontiff, Journal of Finance, 2016 整理</footer></div><p><a href="/quant/fml-online-learning">上一课</a>让参数能跟住缓慢变化，但不是所有变化都该被追：有些漂移该触发重训，有些该触发降仓甚至停机。缺口是分流器：怎么发现、怎么归因、怎么响应。<a href="/quant/live-drift-monitor">实盘漂移监测</a>已立顺序检验与预指定原假设的纪律——监测只读，穿带后的改动是新试验。本课深化发现之后的另一半：分类、诊断与处置路径。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>漂移分三类，响应各不相同。协变量漂移：\\(P(X)\\) 移了，模型在被外推进没见过的区域使用；概念漂移：\\(P(y\\mid X)\\) 变了，同样的特征不再同样兑现——alpha 衰减或反转；管道漂移：<a href="/quant/fml-feature-store-deep">影子对比</a>发散，是管道不是市场。混淆的代价不对称：把管道漂移当概念漂移，会无谓重训，而重训修不了管道；把概念漂移当协变量漂移，会继续追一个正在消失的信号，在噪声上加仓。实务的根本难点：概念漂移不可直接观测——\\(y\\) 要等滞后才知道，只能从 IC 与残差间接推断，而推断可用的窗口与信号半衰期同量级，检测天然滞后于伤害。</p><p><span class="marginnote">PSI（群体稳定性指数）翻译成大白话：把新数据的特征分箱，跟训练时比每一箱的占比，差距越大分越高——就像点名时数每个座位区到了多少人，坐的位置明显变了就报警。经验上 PSI 超过 0.25 通常认为分布显著移动。</span></p>',6)),(B(),r(i,null,{default:e(()=>[l(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20LR%0A%20%20ROOT%5B%22%E4%B8%89%E7%B1%BB%E6%BC%82%E7%A7%BB%22%5D%20--%3E%20COV%5B%22%E5%8D%8F%E5%8F%98%E9%87%8F%E6%BC%82%E7%A7%BB%EF%BC%9AP(X)%20%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20ROOT%20--%3E%20CON%5B%22%E6%A6%82%E5%BF%B5%E6%BC%82%E7%A7%BB%EF%BC%9AP(y%20mid%20X)%20%E6%94%B9%E5%8F%98%22%5D%0A%20%20ROOT%20--%3E%20PIPE%5B%22%E7%AE%A1%E9%81%93%E6%BC%82%E7%A7%BB%EF%BC%9A%E5%BD%B1%E5%AD%90%E5%AF%B9%E6%AF%94%E5%8F%91%E6%95%A3%22%5D%0A%20%20COV%20--%3E%20C1%5B%22%E8%BE%93%E5%85%A5%E5%B1%82%20PSI%20%E4%B8%8E%20KS%20%E5%8F%AF%E8%A7%81%22%5D%0A%20%20CON%20--%3E%20C2%5B%22%E5%8F%AA%E8%83%BD%E4%BB%8E%20IC%20%E4%B8%8E%E6%AE%8B%E5%B7%AE%E9%97%B4%E6%8E%A5%E6%8E%A8%E6%96%AD%22%5D%0A%20%20PIPE%20--%3E%20C3%5B%22%E5%8F%8C%E8%B7%91%E5%B7%AE%E5%BC%82%E7%AB%8B%E5%8D%B3%E5%8F%AF%E8%A7%81%22%5D%0A%20%20C1%20--%3E%20R1%5B%22%E5%93%8D%E5%BA%94%EF%BC%9A%E5%A4%96%E6%8E%A8%E6%88%AA%E6%96%AD%22%5D%0A%20%20C2%20--%3E%20R2%5B%22%E5%93%8D%E5%BA%94%EF%BC%9A%E9%87%8D%E8%AE%AD%E6%88%96%E5%81%9C%E6%9C%BA%22%5D%0A%20%20C3%20--%3E%20R3%5B%22%E5%93%8D%E5%BA%94%EF%BC%9A%E4%BF%AE%E7%AE%A1%E9%81%93%E8%80%8C%E9%9D%9E%E9%87%8D%E8%AE%AD%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"方法",tabindex:"-1"},[a("方法 "),A("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("三段式。发现：分层监测，输入层看特征分布的 PSI 与 KS，输出层看加权 IC 与扣费残差（主路径），执行层看实现缺口（辅助路径），管道层看双跑差异；每层的状态机与阈值在上线时定带，与"),A("a",{href:"/quant/live-drift-monitor"},"实盘漂移监测"),a("的预指定纪律一致。诊断走分流树：先查管道（影子差异归因到列），再查协变量（哪族特征移了、是否进入外推区），最后才轮到概念（条件关系是否仍成立）。响应按诊断分流：管道问题修管道；协变量漂移做外推截断并加强该族监控；概念漂移按衰减预算决定重训、降仓或停机。响应的账：每次重训都是新试验，计入 \\(N\\)；重训产物走 challenger 影子盘，按晋升判据顶替，不许直接换。")],-1)),(B(),r(i,null,{default:e(()=>[l(t,{id:"mermaid-23",class:"mermaid",graph:"flowchart%20TD%0A%20%20MON%5B%22%E5%88%86%E5%B1%82%E7%9B%91%E6%B5%8B%EF%BC%9A%E8%BE%93%E5%85%A5%E3%80%81%E8%BE%93%E5%87%BA%E3%80%81%E6%89%A7%E8%A1%8C%E3%80%81%E7%AE%A1%E9%81%93%22%5D%20--%3E%20ALARM%5B%22%E9%A2%84%E5%86%99%E7%8A%B6%E6%80%81%E6%9C%BA%E6%8A%A5%E8%AD%A6%22%5D%0A%20%20ALARM%20--%3E%20PIPE%7B%22%E5%BD%B1%E5%AD%90%E5%B7%AE%E5%BC%82%E5%8F%91%E6%95%A3%EF%BC%9F%22%7D%0A%20%20PIPE%20--%3E%7C%22'%E6%98%AF'%22%7C%20FIXP%5B%22%E4%BF%AE%E7%AE%A1%E9%81%93%E4%B8%8E%E7%89%B9%E5%BE%81%E5%A5%91%E7%BA%A6%22%5D%0A%20%20PIPE%20--%3E%7C%22'%E5%90%A6'%22%7C%20COV%7B%22%E7%89%B9%E5%BE%81%E5%88%86%E5%B8%83%E5%A4%96%E6%8E%A8%EF%BC%9F%22%7D%0A%20%20COV%20--%3E%7C%22'%E6%98%AF'%22%7C%20TRUNC%5B%22%E5%A4%96%E6%8E%A8%E6%88%AA%E6%96%AD%20%E5%8A%A0%20%E6%97%8F%E7%BA%A7%E7%9B%91%E6%8E%A7%22%5D%0A%20%20COV%20--%3E%7C%22'%E5%90%A6'%22%7C%20CONC%5B%22%E6%A6%82%E5%BF%B5%E6%BC%82%E7%A7%BB%EF%BC%9A%E5%AF%B9%E8%A1%B0%E5%87%8F%E9%A2%84%E7%AE%97%E5%86%B3%E7%AD%96%22%5D%0A%20%20CONC%20--%3E%20RETRAIN%5B%22%E9%87%8D%E8%AE%AD%EF%BC%9Achallenger%20%E5%BD%B1%E5%AD%90%E5%90%8E%E6%99%8B%E5%8D%87%22%5D%0A%20%20CONC%20--%3E%20CUT%5B%22%E9%99%8D%E4%BB%93%22%5D%0A%20%20CONC%20--%3E%20STOP%5B%22%E5%81%9C%E6%9C%BA%22%5D%0A%20%20RETRAIN%20--%3E%20N1%5B%22%E8%AE%A1%E5%85%A5%20N%20%E5%8F%B0%E8%B4%A6%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么「追」要分情况：在线学习能吸收的是慢变参数漂移，概念漂移里信号消失的那部分追不动——重训是在残存信号上重新拟合，期望收益是残存信号的收益减去切换成本；若信号已死，重训的最优输出其实是「不交易」，而重训流程没有这个输出选项时，它必然产出另一个会交易的模型。重训作为响应因此有系统性正偏差：它总是给出一个新模型，从不给出「不该有模型」。阈值为什么必须含衰减预算：若原假设写成「IC 等于回测」，一切真实策略都会报警——衰减是常态；原假设应写成「衰减不超过事前声明的预算」，报警才携带信息。停机不是失败：与<a href="/quant/fml-model-selection-protocol">模型选择协议</a>的弃权同构，它是分流树的合法出口，而且是长期最常见的出口。</p><p><span class="marginnote">衰减预算的数字实例：上线时声明「IC 从 0.05 起，年衰减不超过 0.01」，那么两年后带内下限就是 0.05 − 2×0.01 = 0.03；实测加权 IC 掉到 0.025 时先降仓，而不是等它转负才动作。</span></p><p><span class="marginnote">重训的正偏差可以类比成只带锤子的修理工：无论什么毛病，交付物永远是一次敲打。信号已死时正确答案是「不交易」，但重训流程的产品目录里没有这一项，它只能交付一个还会交易的新模型——工具决定了答案。</span></p><p><span class="marginnote">常见误区：把回撤变大直接当成概念漂移。回撤可能来自执行缺口恶化或者纯粹运气，特征分布与 IC 都没变；分流树第一层先查管道，就是在防止把执行问题错当信号问题来治——药方完全不同。</span></p><p><span class="marginnote">衰减预算的写法：上线文档应写「预期 IC 年衰减不超过 \\(x\\)，加权 IC 低于带 \\(y\\) 触发降仓」，而不是「IC 转负才停」。把停机线画在转负处，等于把整段衰减全额兑现后才承认它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>顺序检验的统计量（CUSUM、递归残差）已有专课，体制识别（HMM 一类）与检验的分工亦已交代，本课只做分流。漂移管理不回答「信号为什么死」——归因到因子层面是因子研究的题目；特征修复与回填的工程归<a href="/quant/fml-feature-store-deep">特征存储</a>。也不把回撤当漂移：执行缺口恶化不是概念漂移，分流树第一层就把它们分开听。最后，漂移管理的所有动作——重训、降仓、停机——都必须留痕进审计包，这是下一课的对象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>漂移三类：协变量、概念、管道；分流树按「先管道、再协变量、后概念」排序诊断。</li><li>概念漂移不可直接观测，检测天然滞后；阈值必须含预声明的衰减预算。</li><li>重训是系统性正偏差的响应：它总会产出新模型，从不输出「不该有模型」。</li><li>每次重训计入 \\(N\\)，challenger 影子盘后按判据晋升；停机是合法出口。</li><li>出处：Gama, Žliobaitė, Bifet, Pechenizkiy and Bouchachia, <em>ACM Computing Surveys</em>, 2014；McLean and Pontiff, <em>JF</em>, 2016；Brown, Durbin and Evans, <em>JRSS-B</em>, 1975。</li></ul>',10))])}const P=o(d,[["render",m]]);export{c as __pageData,P as default};
